  render(state);
  const consumer = ActionCable.createConsumer('/cable');
  const subscription = consumer.subscriptions.create({ channel: 'GameChannel', code: root.dataset.code, presence: root.dataset.presence, watch_counts: moderator }, {
    connected() { connected = true; connectionStatus.textContent = 'Live'; scheduleRefresh(); },
    disconnected() { connected = false; connectionStatus.textContent = 'Reconnecting…'; },
    received() { scheduleRefresh(); },
    rejected() { connected = false; scheduleRefresh(); }
  });
  setInterval(() => { if (connected && state.phase !== 'ended') subscription.perform('heartbeat'); }, 15000);
  async function poll() {
    await refresh();
    const delay = failures ? Math.min(30000, 1500 * 2 ** failures) : connected ? 15000 : 2500;
    setTimeout(poll, delay * (0.85 + Math.random() * 0.3));
  }
  setTimeout(poll, 3000 + Math.random() * 2000);
  document.addEventListener('visibilitychange', () => { if (!document.hidden) scheduleRefresh(); });
  window.addEventListener('online', scheduleRefresh);
  window.addEventListener('pagehide', () => consumer.disconnect());
  window.addEventListener('pageshow', (event) => { if (event.persisted) { consumer.connect(); scheduleRefresh(); } });
})();
