/* Live games: projector-friendly stage and touch-friendly phones. */
[hidden] { display: none !important; }
.live-stage { padding-bottom: 40px; }
.live-stage h1, .live-question { overflow-wrap: anywhere; }
.live-heading { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-bottom: 24px; font-size: 15px; }
.live-badge { border-radius: 30px; background: var(--c-pink); color: white; padding: 8px 16px; font-weight: 800; letter-spacing: .08em; }
.live-lobby { display: grid; grid-template-columns: minmax(0, 1fr) minmax(220px, 320px); gap: 40px; align-items: center; padding: 32px 0; }
.live-lobby h2 { font-size: clamp(26px, 3vw, 44px); }
.join-link { font-size: clamp(22px, 2.5vw, 38px); font-weight: 800; overflow-wrap: anywhere; }
.join-qr { background: white; padding: 24px; border-radius: 20px; }
.join-qr svg { display: block; width: 100%; height: auto; }
.live-counter { display: inline-block; font-size: clamp(24px, 3vw, 40px); font-weight: 800; margin: 12px 0 28px; }
.live-options { list-style: none; padding: 0; margin: 24px 0; display: grid; gap: 12px; }
.live-options .play-option { width: 100%; height: 100%; text-align: left; margin: 0; }
.live-options--stage { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.live-options--stage .play-option { font-size: clamp(22px, 2.5vw, 38px); cursor: default; flex-wrap: wrap; }
.live-options--stage .play-option__letter { font-size: 20px; width: 44px; height: 44px; }
.live-options .play-option.is-correct { border-color: var(--c-success); box-shadow: inset 0 0 0 2px var(--c-success); }
.live-correct { border-radius: 30px; padding: 5px 12px; font-size: 15px; background: #007a49; color: white; font-weight: 800; }
.live-option-count { font-size: 20px; font-weight: 800; }
.live-phone { max-width: 620px; margin-inline: auto; padding-bottom: 40px; }
.live-phone .live-question { font-size: clamp(26px, 6vw, 38px); line-height: 1.15; white-space: pre-line; }
.live-phone .play-option { flex-wrap: wrap; min-height: 70px; }
.live-phone .play-option:disabled { cursor: default; opacity: 1; }
.live-connection { font-size: 13px; text-align: right; margin: 10px 0 24px; }
.player-greeting { font-size: 24px; margin-bottom: 28px; overflow-wrap: anywhere; }
.join-title { font-size: 38px; }
.live-hint { font-size: 15px; line-height: 1.6; }
.live-waiting { padding-block: 40px; font-size: 22px; font-weight: 600; }
.live-message { margin-top: 20px; font-size: 16px; font-weight: 600; }
.live-ending { margin-top: 50px; }
.live-history { display: flex; flex-wrap: wrap; gap: 16px; justify-content: space-between; align-items: center; margin-top: 16px; }
@media (max-width: 680px) {
  .live-lobby, .live-options--stage { grid-template-columns: 1fr; }
  .join-qr { width: 250px; }
  .live-lobby { gap: 12px; }
}
